// BodyArcade service worker. Generated by release/build.ts from release/sw.template.js; do not edit dist/sw.js.
//
// Caches (anything else, including every cache of the old site such as "ba-20261023b", is deleted on activate):
//   ba-shell-<build>       precached at install from the build manifest: the hashed scripts, styles, fonts and
//                          pictures of this build, and the app's start pages; visited pages are added as they load
//   ba-lib-<version>       the pose model and its WASM, cached on first use and kept across builds (they are pinned)
//   ba-media-v1            same-origin pictures and fonts outside the build folder (the guides' pictures)
//
// Strategies: hashed build files cache first (they never change under one name); pages network first with a
// time limit, then the cached copy of that page, then the cached start page of its language (the app draws the
// route itself); /api/*, other origins and non-GET requests are never touched.
/* eslint-disable no-restricted-globals */
const CONFIG = /*__CONFIG__*/ { build: 'dev', precache: [], startPages: { en: '/' }, libPrefixes: ['/vendor/mediapipe/'], libCache: 'ba-lib-dev', navTimeoutMs: 3500 };

const SHELL = `ba-shell-${CONFIG.build}`;
const LIB = CONFIG.libCache;
const MEDIA = 'ba-media-v1';
const KEEP = new Set([SHELL, LIB, MEDIA]);

const sameOrigin = (url) => url.origin === self.location.origin;
const isLib = (path) => CONFIG.libPrefixes.some((p) => path.startsWith(p));
const isBuildFile = (path) => path.startsWith('/static/');
const isMedia = (path) => /\.(?:png|jpe?g|webp|avif|gif|svg|ico|woff2?)$/i.test(path);
const never = (path) => path.startsWith('/api/') || path === '/sw.js' || path === '/sw-register.js' || path === '/version.json';
const cacheable = (res) => !!res && res.ok && res.status === 200 && (res.type === 'basic' || res.type === 'default');

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    // One failed file must not leave the worker uninstalled: each is fetched on its own and the misses are retried
    // the next time they are used.
    await Promise.all(CONFIG.precache.map(async (path) => {
      try {
        const res = await fetch(new Request(new URL(path, self.location.origin).href, { cache: 'reload' }));
        if (cacheable(res)) await cache.put(path, res);
      } catch { /* offline during install: cached on first use instead */ }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((n) => !KEEP.has(n)).map((n) => caches.delete(n)));
    if (self.registration && self.registration.navigationPreload) {
      try { await self.registration.navigationPreload.enable(); } catch { /* not supported */ }
    }
    await self.clients.claim();
  })());
});

async function cacheFirst(request, cacheName) {
  const hit = await caches.match(request, { cacheName });
  if (hit) return hit;
  const res = await fetch(request);
  if (cacheable(res) && !request.headers.has('range')) {
    const copy = res.clone();
    caches.open(cacheName).then((c) => c.put(request, copy)).catch(() => undefined);
  }
  return res;
}

async function staleWhileRevalidate(request, event) {
  const cache = await caches.open(MEDIA);
  const hit = await cache.match(request);
  const update = fetch(request).then((res) => {
    if (cacheable(res)) { const copy = res.clone(); return cache.put(request, copy).then(() => res); }
    return res;
  });
  if (hit) {
    event.waitUntil(update.catch(() => undefined));
    return hit;
  }
  return update;
}

async function networkFirst(request) {
  try {
    const res = await fetch(request);
    if (cacheable(res)) { const copy = res.clone(); caches.open(SHELL).then((c) => c.put(request, copy)).catch(() => undefined); }
    return res;
  } catch (e) {
    const hit = await caches.match(request);
    if (hit) return hit;
    throw e;
  }
}

/** The cached start page for an address: the language prefix of the path, else English. */
function startPageFor(path) {
  const lang = Object.keys(CONFIG.startPages).find((l) => l !== 'en' && (path === `/${l}` || path.startsWith(`/${l}/`)));
  return CONFIG.startPages[lang || 'en'];
}

async function page(event) {
  const request = event.request;
  const path = new URL(request.url).pathname;
  const network = (async () => {
    const preloaded = event.preloadResponse ? await event.preloadResponse.catch(() => undefined) : undefined;
    const res = preloaded || await fetch(request);
    if (cacheable(res) && !res.redirected) { const copy = res.clone(); caches.open(SHELL).then((c) => c.put(path, copy)).catch(() => undefined); }
    return res;
  })();
  const fromCache = async () => (await caches.match(path)) || (await caches.match(startPageFor(path)));
  let timer;
  const slow = new Promise((resolve) => { timer = setTimeout(() => resolve('slow'), CONFIG.navTimeoutMs); });
  try {
    const first = await Promise.race([network, slow]);
    if (first !== 'slow') return first;
    // A slow network ("lie-fi"): the cached copy now, the network answer still updates the cache.
    const cached = await fromCache();
    if (cached) { event.waitUntil(network.catch(() => undefined)); return cached; }
    return await network;
  } catch {
    const cached = await fromCache();
    if (cached) return cached;
    return Response.error();
  } finally {
    clearTimeout(timer);
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (!sameOrigin(url) || never(url.pathname)) return;
  if (request.mode === 'navigate') { event.respondWith(page(event)); return; }
  if (isLib(url.pathname)) { event.respondWith(cacheFirst(request, LIB)); return; }
  if (isBuildFile(url.pathname)) { event.respondWith(cacheFirst(request, SHELL)); return; }
  if (isMedia(url.pathname)) { event.respondWith(staleWhileRevalidate(request, event)); return; }
  event.respondWith(networkFirst(request));
});
